solution.sanitized:
def weighted_average(pairs):
    numerator = denominator = 0
    for value, weight in pairs:
        if weight < 0:
            raise ValueError("negative weight")
        numerator += value * weight
        denominator += weight
    if denominator == 0:
        raise ValueError("zero weight")
    return numerator / denominator

